 'use client';import{useEffect,useState}from'react';import{api}from'../../lib/api';const money=(n:number)=>`₦${Math.round(n/100).toLocaleString('en-NG')}`;export default function Analytics(){const[r,setR]=useState('30'),[d,setD]=useState<any>(),[e,setE]=useState('');useEffect(()=>{const end=new Date(),start=new Date(end.getTime()-(+r-1)*86400000);api(`/api/vendor/analytics?from=${start.toISOString()}&to=${end.toISOString()}`).then(setD).catch(x=>setE(x.message))},[r]);if(!d)return <main className="shell"><div className="card">{e||'Loading analytics…'}</div></main>;const s=d.summary,max=Math.max(1,...(d.daily||[]).map((x:any)=>x.revenue));return <main className="shell"><div className="page-heading-row"><div><div className="eyebrow">BUSINESS PERFORMANCE</div><h1>Analytics</h1><p className="muted">Sales, orders and product performance for your store.</p></div><select className="input compact" value={r} onChange={x=>setR(x.target.value)}><option value="7">Last 7 days</option><option value="30">Last 30 days</option><option value="90">Last 90 days</option></select></div><div className="metric-grid"><div className="metric-card"><span>Revenue</span><strong>{money(s.revenue)}</strong></div><div className="metric-card"><span>Orders</span><strong>{s.orders}</strong></div><div className="metric-card"><span>Average order</span><strong>{money(s.averageOrderValue)}</strong></div><div className="metric-card"><span>Rating</span><strong>{Number(s.rating).toFixed(1)} ★</strong></div></div><div className="analytics-grid"><section className="content-card analytics-card"><div className="card-head"><div><span>SALES TREND</span><h2>Daily revenue</h2></div></div><div className="sales-bars">{d.daily.map((x:any)=><div className="sales-bar-wrap" key={x.date} title={money(x.revenue)}><div className="sales-bar" style={{height:`${Math.max(4,x.revenue/max*150)}px`}}/><small>{x.date.slice(5)}</small></div>)}</div></section><section className="content-card analytics-card"><div className="card-head"><div><span>BEST SELLERS</span><h2>Top products</h2></div></div>{d.topProducts.map((x:any,i:number)=><div className="analytics-list-row" key={x.productId}><b>{i+1}</b><div><strong>{x.name}</strong><span>{x.quantitySold} sold</span></div><em>{money(x.revenue)}</em></div>)}</section></div></main>}